var i=`theory-of-constraints`;var o=109;var n={en:[{id:`T109-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Theory of Constraints`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`The Theory of Constraints holds that overall throughput is limited by a small number of bottlenecks.`},{id:`B`,text:`An ADR records an architectural choice, the context that motivated it, alternatives, consequences and status.`},{id:`C`,text:`Brooks's Law warns that adding people to a late software project may make it later because onboarding and communication cost time.`},{id:`D`,text:`The Pareto principle is a heuristic that a minority of causes often account for a majority of outcomes.`}]},{id:`T109-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Theory of Constraints`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Start with workload, constraints, invariants and failure tolerance.`},{id:`B`,text:`Measure arrivals, completed throughput, waiting and processing time over compatible boundaries and steady periods.`},{id:`C`,text:`Rank performance bottlenecks, incident sources, customer complaints or feature adoption using real data.`},{id:`D`,text:`Identify the current constraint, exploit it efficiently, subordinate upstream work to its capacity, elevate capacity when justified and repeat as bottlenecks move.`}]},{id:`T109-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A document-processing pipeline has fast uploads and notifications but one slow OCR stage.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Database contention may lower it further.`},{id:`B`,text:`Increasing upload workers only grows the queue; parallelizing or optimizing OCR may improve completion throughput.`},{id:`C`,text:`A worker queue processing 20 jobs per second with an average job time in the system of 3 seconds has roughly 60 jobs in flight/on average under stable conditions.`},{id:`D`,text:`Factor in support, edge cases and reliability of the automation.`}]},{id:`T109-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Theory of Constraints`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Amdahl assumes a fixed workload and idealized parallel execution; real workloads can grow and require Gustafson-style scaling analysis.`},{id:`B`,text:`Buying is not zero engineering; vendor contracts, outages and migrations are part of the system.`},{id:`C`,text:`An ADR should not be a lengthy design specification or a way to rubber-stamp decisions after implementation.`},{id:`D`,text:`Bottlenecks shift under different workloads.`}]},{id:`T109-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`Improving non-bottlenecks rarely improves system-level outcomes.`}]}]},{id:`T109-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Improving any non-bottleneck stage always increases end-to-end throughput.`}]}]},{id:`T109-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Pushing a bottleneck to maximum CPU can destabilize latency and reliability; protect spare capacity where spikes are expected.`}]}]},{id:`T109-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Theory of Constraints`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Reducing work-in-progress at the bottleneck always lowers throughput to zero.`},{id:`B`,text:`Adding developers to a late project always reduces remaining delivery time.`},{id:`C`,text:`The Theory of Constraints holds that overall throughput is limited by a small number of bottlenecks.`},{id:`D`,text:`Identify the current constraint, exploit it efficiently, subordinate upstream work to its capacity, elevate capacity when justified and repeat as bottlenecks move.`}]},{id:`T109-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Theory of Constraints`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Improving any non-bottleneck stage always increases end-to-end throughput.`},{id:`B`,text:`Trade-offs disappear if a team chooses the most popular technology.`},{id:`C`,text:`Pushing a bottleneck to maximum CPU can destabilize latency and reliability; protect spare capacity where spikes are expected.`},{id:`D`,text:`Increasing upload workers only grows the queue; parallelizing or optimizing OCR may improve completion throughput.`}]},{id:`T109-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A document-processing pipeline has fast uploads and notifications but one slow OCR stage.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to create a build/buy matrix for authentication, email and booking rules, with vendor exit plans and three-year total-cost ranges.`},{id:`B`,text:`Ask an agent to benchmark sequential and parallel report generation, estimate serial fraction, compare observed speedup with Amdahl's bound and explain overhead.`},{id:`C`,text:`Ask an agent to draft an ADR comparing event-driven and synchronous booking workflows, then have it list evidence that would overturn the selected option.`},{id:`D`,text:`Ask an agent to map throughput across an import pipeline, identify the bottleneck from measurements and propose staged improvements with before/after flow metrics.`}]},{id:`T109-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`What happens to total throughput if you double capacity everywhere except at the constraint?`}]}]},{id:`T109-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A document-processing pipeline has fast uploads and notifications but one slow OCR stage.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Theory of Constraints`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T109-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A document-processing pipeline has fast uploads and notifications but one slow OCR stage.`,b:!0},{t:` — propose three checks for `},{t:`Theory of Constraints`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T109-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A document-processing pipeline has fast uploads and notifications but one slow OCR stage.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T109-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Theory of Constraints`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A document-processing pipeline has fast uploads and notifications but one slow OCR stage.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T109-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Теорія обмежень`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Теорія обмежень стверджує, що загальну пропускну здатність обмежує невелика кількість вузьких місць.`},{id:`B`,text:`ADR фіксує архітектурний вибір, його контекст, альтернативи, наслідки та стан.`},{id:`C`,text:`Закон Брукса попереджає, що додавання людей до запізнілого проєкту може ще більше затримати його через навчання та комунікацію.`},{id:`D`,text:`Принцип Парето — евристика, за якою невелика частина причин часто створює більшість результатів.`}]},{id:`T109-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Теорія обмежень`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Починайте з навантаження, обмежень, інваріантів і допустимих відмов.`},{id:`B`,text:`Вимірюйте надходження, завершену пропускну здатність, очікування й обробку в однакових межах і стабільному періоді.`},{id:`C`,text:`Ранжуйте вузькі місця, причини інцидентів, скарги чи використання фіч за даними.`},{id:`D`,text:`Визначте обмеження, використайте його ефективно, узгодьте роботу інших ділянок із його потужністю, збільште потужність за потреби та повторіть цикл.`}]},{id:`T109-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Конвеєр документів має швидке завантаження й сповіщення, але повільне OCR.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Конкуренція за БД зменшить результат.`},{id:`B`,text:`Додавання upload-воркерів лише збільшує чергу; оптимізація OCR може підвищити загальну пропускну здатність.`},{id:`C`,text:`Черга, що обробляє 20 задач за секунду із середнім часом перебування 3 секунди, за стабільних умов має приблизно 60 задач у системі в середньому.`},{id:`D`,text:`Врахуйте підтримку, винятки й надійність процесу.`}]},{id:`T109-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Теорія обмежень`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Амдал припускає фіксоване завдання й ідеальну паралельність; реальне навантаження може зростати, де корисний аналіз Густафсона.`},{id:`B`,text:`Купівля не означає нуль інженерної роботи: контракти, збої постачальника й міграції стають частиною системи.`},{id:`C`,text:`ADR не має бути багатосторінковою специфікацією чи формальністю після реалізації.`},{id:`D`,text:`Вузькі місця змінюються за різного навантаження.`}]},{id:`T109-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Оптимізація інших ділянок рідко покращує результат системи.`}]}]},{id:`T109-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Прискорення будь-якого етапу, що не є вузьким місцем, завжди збільшує пропускну здатність.`}]}]},{id:`T109-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Вичавлювання 100% CPU може погіршити затримку й надійність; залишайте резерв під піки.`}]}]},{id:`T109-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Теорія обмежень`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Скорочення незавершеної роботи біля вузького місця завжди знижує потік до нуля.`},{id:`B`,text:`Додавання розробників у запізнілий проєкт завжди скорочує термін завершення.`},{id:`C`,text:`Теорія обмежень стверджує, що загальну пропускну здатність обмежує невелика кількість вузьких місць.`},{id:`D`,text:`Визначте обмеження, використайте його ефективно, узгодьте роботу інших ділянок із його потужністю, збільште потужність за потреби та повторіть цикл.`}]},{id:`T109-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Теорія обмежень`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Прискорення будь-якого етапу, що не є вузьким місцем, завжди збільшує пропускну здатність.`},{id:`B`,text:`Компроміси зникають, якщо команда вибрала найпопулярнішу технологію.`},{id:`C`,text:`Вичавлювання 100% CPU може погіршити затримку й надійність; залишайте резерв під піки.`},{id:`D`,text:`Додавання upload-воркерів лише збільшує чергу; оптимізація OCR може підвищити загальну пропускну здатність.`}]},{id:`T109-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Конвеєр документів має швидке завантаження й сповіщення, але повільне OCR.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента скласти матрицю build/buy для входу, пошти та правил бронювання з планом виходу від постачальника й трирічною оцінкою витрат.`},{id:`B`,text:`Попросіть агента заміряти послідовне й паралельне формування звіту, оцінити послідовну частку, зіставити результат із законом Амдала та пояснити накладні витрати.`},{id:`C`,text:`Попросіть агента підготувати ADR про синхронний чи подієвий процес бронювання та перелічити докази для перегляду вибору.`},{id:`D`,text:`Попросіть агента зіставити пропускну здатність етапів імпорту, знайти вузьке місце за вимірами й запропонувати поетапні покращення з порівнянням результату.`}]},{id:`T109-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Що станеться із загальною пропускною здатністю, якщо подвоїти потужність усюди, крім вузького місця?`}]}]},{id:`T109-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Конвеєр документів має швидке завантаження й сповіщення, але повільне OCR.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Теорія обмежень`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T109-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Конвеєр документів має швидке завантаження й сповіщення, але повільне OCR.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Теорія обмежень`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T109-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Конвеєр документів має швидке завантаження й сповіщення, але повільне OCR.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T109-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Теорія обмежень`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Конвеєр документів має швидке завантаження й сповіщення, але повільне OCR.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var s={slug:i,topicId:109,questions:n};export{s as default,n as questions,i as slug,o as topicId};